/*
 * Foundation aptitude is deliberately a small, curated placement bank rather
 * than a random arithmetic generator.  Each topic has a consistent 5/10/5
 * Conceptual / Standard / Advanced mix.  The checks at the bottom make a bad
 * option set or an accidental answer-key mismatch fail during development.
 */
const levelFor = index => index < 5 ? 'Conceptual Placement' : index < 15 ? 'Standard Placement' : 'Advanced Placement';
const difficultyFor = index => index < 5 ? 'Easy' : index < 15 ? 'Medium' : 'Hard';
const timeFor = index => index < 5 ? 45 : index < 15 ? 60 : 90;
const text = value => String(value);
const gcd = (a, b) => b ? gcd(b, a % b) : Math.abs(a);
const fraction = (numerator, denominator) => {
  const factor = gcd(numerator, denominator);
  return `${numerator / factor}/${denominator / factor}`;
};
const format = value => Number.isInteger(value) ? String(value) : String(Number(value.toFixed(2)));

const optionSet = (answer, wrong, seed) => {
  const correct = text(answer);
  const choices = [correct, ...wrong.map(text)].filter((item, index, all) => all.indexOf(item) === index);
  if (choices.length !== 4) throw new Error(`Question option set needs four unique values; got ${choices.join(', ')}`);
  const offset = seed % 4;
  const options = [...choices.slice(offset), ...choices.slice(0, offset)];
  return { options, correctAnswer: options.indexOf(correct) };
};
const question = (topic, index, { prompt, answer, wrong, explanation, shortcut = null, formulaIds = [], tags = [], setId = null, setContext = null }) => ({
  id: `foundation-${topic}-${String(index + 1).padStart(3, '0')}`,
  track: 'foundation',
  topic,
  placementLevel: levelFor(index),
  difficulty: difficultyFor(index),
  estimatedTimeSeconds: timeFor(index),
  question: prompt,
  ...optionSet(answer, wrong, index),
  explanation,
  shortcut,
  formulaIds,
  tags,
  setId,
  setContext
});
const q = (topic, index, fields) => question(topic, index, fields);

