    if (i % 5 === 0) { const answer = `${b / divisor}:${a / divisor}`; return q('percentages', i, { prompt: `${a}% of A equals ${b}% of B. What is A:B?`, answer, wrong: [`${a / divisor}:${b / divisor}`, `${a}:${b}`, `${b / 5}:${a / 5}`], explanation: `${a}A/100 = ${b}B/100, so A:B = ${b}:${a}; reducing gives ${answer}.`, shortcut: 'Cross the percentages: A:B is the reverse of the percentage ratio.', formulaIds: ['percentage-change'], tags: ['Percentage relationship', 'Ratio'] }); }
