    if (i % 5 === 1) { const total = (x + y) * 90; const answer = total * y / (x + y); return q('ratio-proportion', i, { prompt: `₹${total} is divided between A and B in the ratio ${x}:${y}. What does B receive?`, answer: `₹${answer}`, wrong: [`₹${total * x / (x + y)}`, `₹${total / 2}`, `₹${answer + 135}`], explanation: `There are ${x + y} parts. B has ${y}, so B = ${y}/${x + y} × ${total} = ₹${answer}.`, shortcut: 'Find one ratio part: ₹${total / (x + y)}.', formulaIds: ['ratio-share'], tags: ['Ratio share', 'Distribution'] }); }
    if (i % 5 === 2) { const boys = 4 + i % 3; const girls = 5 + i % 4; const add = girls; const answer = `${boys}:${girls + add}`; return q('ratio-proportion', i, { prompt: `The ratio of boys to girls is ${boys}:${girls}. If ${add} girls join, what is the new ratio?`, answer, wrong: [`${boys + add}:${girls}`, `${boys}:${girls}`, `${boys + add}:${girls + add}`], explanation: `Only the girls count changes: ${boys}:(${girls}+${add}) = ${answer}.`, shortcut: 'Update only the group described in the change.', formulaIds: ['ratio-share'], tags: ['Ratio', 'Change'] }); }
