    const original = 80 + i % 4 * 20; const increase = 25; const answer = original * 1.25; return q('ratio-proportion', i, { prompt: `A recipe uses flour and sugar in ratio 5:2. If flour becomes ${increase}% more while sugar stays the same, what is the new ratio?`, answer: `${5 * 1.25}:2`, wrong: ['5:2', `${5}:${2 * 1.25}`, '6:3'], explanation: `Only flour changes: 5 × 1.25 : 2 = 6.25:2, equivalent to 25:8.`, shortcut: 'Apply the percentage multiplier to the affected ratio part only.', formulaIds: ['ratio-share', 'percentage-change'], tags: ['Ratio', 'Percentage'] });
