    if (i % 5 === 1) { const now = 24; const difference = 12; return q('ages', i, { prompt: `The sum of A and B’s ages is ${now + difference}. A is ${difference} years older than B. What is B’s age?`, answer: now / 2, wrong: [difference, now, (now + difference) / 2], explanation: `Let B=x, A=x+${difference}. Then 2x+${difference}=${now + difference}; x=${now / 2}.`, shortcut: 'Subtract the age difference from the sum, then halve.', formulaIds: ['average'], tags: ['Ages', 'Linear equation'] }); }
    if (i % 5 === 2) { const present = 30; const ago = 5; const ratio = '5:3'; const answer = present + ago; return q('ages', i, { prompt: `${ago} years ago, A:B was ${ratio}. If B is now ${present}, what is A’s current age?`, answer, wrong: [present, present * 5 / 3, answer + ago], explanation: `B was ${present - ago}, so one ratio part is ${(present - ago) / 3}; A was ${(present - ago) / 3 * 5}, hence now ${answer}.`, shortcut: 'First move both ages to the time where the ratio is given.', formulaIds: ['ratio-share'], tags: ['Ages', 'Ratio'] }); }
    if (i % 5 === 3) { const mother = 42; const daughter = 14; const years = 14; return q('ages', i, { prompt: `A mother is ${mother} and her daughter is ${daughter}. After how many years will the mother be twice the daughter’s age?`, answer: years, wrong: [7, 21, 0], explanation: `42+x = 2(14+x). Solving gives x=14.`, shortcut: 'Use an equation; ratios change with time.', formulaIds: ['ratio-share'], tags: ['Ages', 'Equation'] }); }
    const a = 18; const b = 30; const multiplier = 2; const answer = (b - multiplier * a) / (multiplier - 1); return q('ages', i, { prompt: `After how many years will a ${b}-year-old be twice as old as an ${a}-year-old?`, answer, wrong: [b - a, a, b / 2], explanation: `${b}+x = 2(${a}+x), so x = ${answer}.`, shortcut: 'Set “older after x” equal to the required multiple of “younger after x”.', formulaIds: ['ratio-share'], tags: ['Ages', 'Algebra'] });
