const logicalReasoning = logicalBank.map(([prompt, answer, wrong, explanation, tag], index) => q('logical-reasoning', index, { prompt, answer, wrong, explanation, shortcut: tag === 'Ranking' ? 'Add positions from both ends and subtract one.' : null, tags: ['Logical reasoning', tag] }));

