export const aptitudeQuestions = {
  ...Object.fromEntries(Object.entries(numericBuilders).map(([id, builder]) => [id, Array.from({ length: 20 }, (_, index) => builder(index))])),
  ...Object.fromEntries(Object.entries(motionBuilders).map(([id, builder]) => [id, Array.from({ length: 20 }, (_, index) => builder(index))])),
  ...Object.fromEntries(Object.entries(algebraBuilders).map(([id, builder]) => [id, Array.from({ length: 20 }, (_, index) => builder(index))])),
  ...Object.fromEntries(Object.entries(geometryBuilders).map(([id, builder]) => [id, Array.from({ length: 20 }, (_, index) => builder(index))])),
  'data-interpretation': dataInterpretation,
  'logical-reasoning': logicalReasoning,
  'verbal-ability': verbalAbility
};

export const validateFoundationCatalog = () => {
  const formulaIds = new Set(formulaCatalog.map(item => item.id));
  const errors = [];
  for (const topic of aptitudeTopics) {
    const questions = aptitudeQuestions[topic.id] || [];
    if (questions.length !== 20) errors.push(`${topic.id}: expected 20 questions, received ${questions.length}`);
    const levelCounts = questions.reduce((all, item) => ({ ...all, [item.placementLevel]: (all[item.placementLevel] || 0) + 1 }), {});
    if (levelCounts['Conceptual Placement'] !== 5 || levelCounts['Standard Placement'] !== 10 || levelCounts['Advanced Placement'] !== 5) errors.push(`${topic.id}: expected a 5/10/5 placement-level mix`);
    questions.forEach(item => {
      if (item.options.length !== 4 || new Set(item.options).size !== 4) errors.push(`${item.id}: needs exactly four distinct options`);
      if (!Number.isInteger(item.correctAnswer) || item.correctAnswer < 0 || item.correctAnswer > 3) errors.push(`${item.id}: invalid correct-answer index`);
      if (!item.explanation || !item.tags.length || item.estimatedTimeSeconds < 30 || item.estimatedTimeSeconds > 90) errors.push(`${item.id}: needs explanation, concepts and a 30–90 second estimate`);
      item.formulaIds.forEach(id => { if (!formulaIds.has(id)) errors.push(`${item.id}: unknown formula ${id}`); });
    });
  }
  return errors;
};

const catalogErrors = validateFoundationCatalog();
if (catalogErrors.length) throw new Error(`Invalid Foundation aptitude catalog:\n${catalogErrors.join('\n')}`);
